export function throttle<TArgs extends unknown[]>(
  fn: (...args: TArgs) => void,
  wait: number,
) {
  let lastRun: number | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let trailingArgs: TArgs | undefined;
  const delay = Math.max(0, wait);
  return (...args: TArgs) => {
    if (delay === 0) {
      fn(...args);
      return;
    }
    const now = Date.now();
    const remaining = lastRun === undefined ? 0 : delay - (now - lastRun);
    if (remaining <= 0) {
      if (timer) clearTimeout(timer);
      timer = undefined;
      trailingArgs = undefined;
      lastRun = now;
      fn(...args);
      return;
    }
    trailingArgs = args;
    if (!timer) {
      timer = setTimeout(() => {
        timer = undefined;
        lastRun = Date.now();
        if (trailingArgs) fn(...trailingArgs);
        trailingArgs = undefined;
      }, remaining);
    }
  };
}

type Timer = ReturnType<typeof setTimeout>;

export function debounce<TArgs extends unknown[]>(
  fn: (...args: TArgs) => void,
  wait: number,
) {
  let timer: Timer | undefined;
  let lastArgs: TArgs | undefined;
  const delay = Math.max(0, wait);

  const debounced = (...args: TArgs) => {
    lastArgs = args;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      const argsToUse = lastArgs;
      lastArgs = undefined;
      if (argsToUse) fn(...argsToUse);
    }, delay);
  };

  debounced.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
    lastArgs = undefined;
  };

  debounced.flush = () => {
    if (!timer || !lastArgs) return;
    clearTimeout(timer);
    timer = undefined;
    const argsToUse = lastArgs;
    lastArgs = undefined;
    fn(...argsToUse);
  };

  return debounced;
}

