import { useState } from "react";

type ProfileValue = {
  name: string;
  email: string;
};

export function ProfileForm({
  onSubmit,
}: {
  onSubmit: (value: ProfileValue) => void;
}) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();

        if (!name || !email.includes("@")) {
          setError("Enter a valid profile");
          return;
        }

        setError("");
        onSubmit({ name, email });
      }}
    >
      <label>
        Name
        <input value={name} onChange={(event) => setName(event.target.value)} />
      </label>

      <label>
        Email
        <input
          value={email}
          onChange={(event) => setEmail(event.target.value)}
        />
      </label>

      {error ? <p>{error}</p> : null}
      <button type="submit">Save</button>
    </form>
  );
}

import { useState } from 'react';
export function ProfileForm({
  onSubmit,
}: {
  onSubmit: (value: { name: string; email: string }) => void;
}) {
  const [value, setValue] = useState({ name: '', email: '' });
  const emailError =
    value.email && !value.email.includes('@') ? 'Enter a valid email' : '';
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (!emailError && value.name && value.email) onSubmit(value);
      }}
    >
      <label>
        Name
        <input
          value={value.name}
          onChange={(event) => setValue({ ...value, name: event.target.value })}
        />
      </label>
      <label>
        Email
        <input
          aria-describedby="email-error"
          value={value.email}
          onChange={(event) =>
            setValue({ ...value, email: event.target.value })
          }
        />
      </label>
      {emailError ? <p id="email-error">{emailError}</p> : null}
      <button type="submit">Save</button>
    </form>
  );
}

import { useMemo, useState } from "react";

type ProfileValue = {
  name: string;
  email: string;
};

type FieldName = keyof ProfileValue;
type FieldErrors = Partial<Record<FieldName, string>>;
type TouchedFields = Partial<Record<FieldName, boolean>>;

const initialValue: ProfileValue = {
  name: "",
  email: "",
};

function validateProfile(value: ProfileValue): FieldErrors {
  const errors: FieldErrors = {};
  const name = value.name.trim();
  const email = value.email.trim();

  if (!name) errors.name = "Enter your name";
  if (!email) errors.email = "Enter your email";
  else if (!email.includes("@")) errors.email = "Enter a valid email";

  return errors;
}

function hasErrors(errors: FieldErrors) {
  return Object.keys(errors).length > 0;
}

export function ProfileForm({
  onSubmit,
}: {
  onSubmit: (value: ProfileValue) => void;
}) {
  const [value, setValue] = useState(initialValue);
  const [touched, setTouched] = useState<TouchedFields>({});
  const [submitted, setSubmitted] = useState(false);
  const errors = useMemo(() => validateProfile(value), [value]);
  const isInvalid = hasErrors(errors);

  function updateField(field: FieldName, nextValue: string) {
    setValue((current) => ({ ...current, [field]: nextValue }));
  }

  function markTouched(field: FieldName) {
    setTouched((current) => ({ ...current, [field]: true }));
  }

  function shouldShowError(field: FieldName) {
    return Boolean(errors[field] && (touched[field] || submitted));
  }

  return (
    <form
      noValidate
      onSubmit={(event) => {
        event.preventDefault();
        setSubmitted(true);

        if (isInvalid) return;

        onSubmit({
          name: value.name.trim(),
          email: value.email.trim(),
        });
      }}
    >
      <label>
        Name
        <input
          aria-describedby={shouldShowError("name") ? "name-error" : undefined}
          aria-invalid={shouldShowError("name")}
          value={value.name}
          onBlur={() => markTouched("name")}
          onChange={(event) => updateField("name", event.target.value)}
        />
      </label>
      {shouldShowError("name") ? <p id="name-error">{errors.name}</p> : null}

      <label>
        Email
        <input
          aria-describedby={
            shouldShowError("email") ? "email-error" : undefined
          }
          aria-invalid={shouldShowError("email")}
          inputMode="email"
          value={value.email}
          onBlur={() => markTouched("email")}
          onChange={(event) => updateField("email", event.target.value)}
        />
      </label>
      {shouldShowError("email") ? (
        <p id="email-error">{errors.email}</p>
      ) : null}

      <button type="submit" disabled={submitted && isInvalid}>
        Save
      </button>
    </form>
  );
}

