import { useState } from "react";

export type Option = { id: string; label: string };

export function Autocomplete({
  search,
  onSelect,
}: {
  search: (query: string) => Promise<Option[]>;
  onSelect: (option: Option) => void;
}) {
  const [query, setQuery] = useState("");
  const [options, setOptions] = useState<Option[]>([]);

  async function handleChange(nextQuery: string) {
    setQuery(nextQuery);

    if (!nextQuery) {
      setOptions([]);
      return;
    }

    setOptions(await search(nextQuery));
  }

  return (
    <div>
      <label>
        Search
        <input
          value={query}
          onChange={(event) => {
            void handleChange(event.target.value);
          }}
        />
      </label>

      <ul role="listbox">
        {options.map((option) => (
          <li key={option.id}>
            <button role="option" onClick={() => onSelect(option)}>
              {option.label}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useState } from 'react';
export type Option = { id: string; label: string };
export function Autocomplete({
  search,
  onSelect,
}: {
  search: (query: string) => Promise<Option[]>;
  onSelect: (option: Option) => void;
}) {
  const [query, setQuery] = useState('');
  const [options, setOptions] = useState<Option[]>([]);
  const [status, setStatus] = useState('idle');
  useEffect(() => {
    if (!query) {
      setOptions([]);
      setStatus('idle');
      return;
    }
    let active = true;
    setStatus('loading');
    search(query).then(
      (items) => {
        if (active) {
          setOptions(items);
          setStatus(items.length ? 'success' : 'empty');
        }
      },
      () => {
        if (active) setStatus('error');
      },
    );
    return () => {
      active = false;
    };
  }, [query, search]);
  return (
    <div>
      <label>
        Search
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
        />
      </label>
      {status === 'loading' ? <p>Loading</p> : null}
      {status === 'empty' ? <p>No results</p> : null}
      <ul role="listbox">
        {options.map((option) => (
          <li key={option.id}>
            <button role="option" onClick={() => onSelect(option)}>
              {option.label}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useId, useMemo, useRef, useState } from "react";

export type Option = { id: string; label: string };

type Status = "idle" | "loading" | "success" | "empty" | "error";

export function Autocomplete({
  search,
  onSelect,
}: {
  search: (query: string) => Promise<Option[]>;
  onSelect: (option: Option) => void;
}) {
  const inputId = useId();
  const listboxId = useId();
  const requestIdRef = useRef(0);
  const [query, setQuery] = useState("");
  const [options, setOptions] = useState<Option[]>([]);
  const [status, setStatus] = useState<Status>("idle");
  const [activeIndex, setActiveIndex] = useState(0);
  const activeOption = options[activeIndex];

  useEffect(() => {
    const normalizedQuery = query.trim();

    if (!normalizedQuery) {
      setOptions([]);
      setStatus("idle");
      setActiveIndex(0);
      return;
    }

    const requestId = ++requestIdRef.current;
    setStatus("loading");

    search(normalizedQuery).then(
      (items) => {
        if (requestId !== requestIdRef.current) return;
        setOptions(items);
        setActiveIndex(0);
        setStatus(items.length ? "success" : "empty");
      },
      () => {
        if (requestId === requestIdRef.current) {
          setOptions([]);
          setStatus("error");
        }
      },
    );
  }, [query, search]);

  const message = useMemo(() => {
    if (status === "loading") return "Loading";
    if (status === "empty") return "No results";
    if (status === "error") return "Could not load results";
    return "";
  }, [status]);

  return (
    <div>
      <label htmlFor={inputId}>Search</label>
      <input
        id={inputId}
        role="combobox"
        aria-autocomplete="list"
        aria-controls={listboxId}
        aria-expanded={options.length > 0}
        aria-activedescendant={
          activeOption ? listboxId + "-" + activeOption.id : undefined
        }
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown") {
            event.preventDefault();
            setActiveIndex((index) => Math.min(options.length - 1, index + 1));
          }

          if (event.key === "ArrowUp") {
            event.preventDefault();
            setActiveIndex((index) => Math.max(0, index - 1));
          }

          if (event.key === "Enter" && activeOption) {
            event.preventDefault();
            onSelect(activeOption);
          }
        }}
      />

      {message ? <p aria-live="polite">{message}</p> : null}

      <ul id={listboxId} role="listbox">
        {options.map((option, index) => (
          <li key={option.id}>
            <button
              id={listboxId + "-" + option.id}
              role="option"
              aria-selected={index === activeIndex}
              onMouseEnter={() => setActiveIndex(index)}
              onClick={() => onSelect(option)}
            >
              {option.label}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

