export async function promiseAll<T extends readonly unknown[]>(
  values: T,
): Promise<{ [K in keyof T]: Awaited<T[K]> }> {
  const results = [] as unknown[];

  for (const value of values) {
    results.push(await value);
  }

  return results as { [K in keyof T]: Awaited<T[K]> };
}

export function promiseAll<T extends readonly unknown[]>(
  values: T,
): Promise<{ [K in keyof T]: Awaited<T[K]> }> {
  return new Promise((resolve, reject) => {
    if (values.length === 0) {
      resolve([] as { [K in keyof T]: Awaited<T[K]> });
      return;
    }
    const results = new Array(values.length);
    let completed = 0;
    values.forEach((value, index) => {
      Promise.resolve(value).then((result) => {
        results[index] = result;
        completed += 1;
        if (completed === values.length)
          resolve(results as { [K in keyof T]: Awaited<T[K]> });
      }, reject);
    });
  });
}

export function promiseAll<T extends readonly unknown[]>(
  values: T,
): Promise<{ [K in keyof T]: Awaited<T[K]> }> {
  return new Promise((resolve, reject) => {
    if (values.length === 0) {
      resolve([] as { [K in keyof T]: Awaited<T[K]> });
      return;
    }

    const results: unknown[] = new Array(values.length);
    let pending = values.length;
    let rejected = false;

    values.forEach((value, index) => {
      Promise.resolve(value).then(
        (result) => {
          if (rejected) return;

          results[index] = result;
          pending -= 1;

          if (pending === 0) {
            resolve(results as { [K in keyof T]: Awaited<T[K]> });
          }
        },
        (error) => {
          if (rejected) return;
          rejected = true;
          reject(error);
        },
      );
    });
  });
}

