export type TabItem = { id: string; title: string; content: React.ReactNode };

export function Tabs({ items }: { items: TabItem[] }) {
  const [activeId, setActiveId] = useState(items[0]?.id);
  const active = items.find((item) => item.id === activeId) ?? items[0];

  return (
    <div>
      {items.map((item) => (
        <button key={item.id} onClick={() => setActiveId(item.id)}>
          {item.title}
        </button>
      ))}
      <section>{active?.content}</section>
    </div>
  );
}

import { useState } from 'react';
export type TabItem = { id: string; title: string; content: React.ReactNode };
export function Tabs({ items }: { items: TabItem[] }) {
  const [activeId, setActiveId] = useState(items[0]?.id);
  const active = items.find((item) => item.id === activeId) ?? items[0];
  const move = (delta: number) => {
    const index = Math.max(
      0,
      items.findIndex((item) => item.id === active?.id),
    );
    setActiveId(items[(index + delta + items.length) % items.length]?.id);
  };
  return (
    <div>
      <div role="tablist">
        {items.map((item) => (
          <button
            key={item.id}
            role="tab"
            aria-selected={item.id === active?.id}
            onClick={() => setActiveId(item.id)}
            onKeyDown={(event) => {
              if (event.key === 'ArrowRight') move(1);
              if (event.key === 'ArrowLeft') move(-1);
            }}
          >
            {item.title}
          </button>
        ))}
      </div>
      <section role="tabpanel">{active?.content}</section>
    </div>
  );
}

import { useId, useState } from "react";

export type TabItem = { id: string; title: string; content: React.ReactNode };

export function Tabs({ items }: { items: TabItem[] }) {
  const baseId = useId();
  const [activeId, setActiveId] = useState(items[0]?.id);
  const active = items.find((item) => item.id === activeId) ?? items[0];
  const activeIndex = Math.max(
    0,
    items.findIndex((item) => item.id === active?.id),
  );

  function move(nextIndex: number) {
    if (items.length === 0) return;
    const normalizedIndex = (nextIndex + items.length) % items.length;
    const next = items[normalizedIndex];
    if (next) setActiveId(next.id);
  }

  return (
    <div>
      <div role="tablist">
        {items.map((item, index) => {
          const selected = item.id === active?.id;
          const tabId = baseId + "-tab-" + item.id;
          const panelId = baseId + "-panel-" + item.id;

          return (
            <button
              id={tabId}
              key={item.id}
              role="tab"
              aria-controls={panelId}
              aria-selected={selected}
              tabIndex={selected ? 0 : -1}
              onClick={() => setActiveId(item.id)}
              onKeyDown={(event) => {
                if (event.key === "ArrowRight") move(index + 1);
                if (event.key === "ArrowLeft") move(index - 1);
                if (event.key === "Home") move(0);
                if (event.key === "End") move(items.length - 1);
              }}
            >
              {item.title}
            </button>
          );
        })}
      </div>
      <section
        id={active ? baseId + "-panel-" + active.id : undefined}
        role="tabpanel"
        aria-labelledby={active ? baseId + "-tab-" + active.id : undefined}
      >
        {items[activeIndex]?.content}
      </section>
    </div>
  );
}

