export function getNextFocusableIndex(
  current: number,
  count: number,
  direction: 1 | -1,
) {
  if (count === 0) return -1;
  return (current + direction + count) % count;
}

export function getNextFocusableIndex(
  current: number,
  count: number,
  direction: 1 | -1,
) {
  if (count <= 0) return -1;
  return (current + direction + count) % count;
}

export function getNextFocusableIndex(
  current: number,
  count: number,
  direction: 1 | -1,
) {
  if (!Number.isInteger(count) || count <= 0) return -1;

  const safeCurrent = Number.isInteger(current)
    ? Math.min(count - 1, Math.max(0, current))
    : 0;

  return (safeCurrent + direction + count) % count;
}

export function getNextFocusableIndex(
  current: number,
  count: number,
  direction: 1 | -1,
) {
  if (count <= 0) return -1;
  return (current + direction + count) % count;
}

export function createDelegatedListHandler(onSelect: (id: string) => void) {
  return (event: Event) => {
    const target = event.target as HTMLElement | null;
    const id = target?.dataset.id;

    if (id) onSelect(id);
  };
}

export function createDelegatedListHandler(onSelect: (id: string) => void) {
  return (event: Event) => {
    const target = event.target as HTMLElement | null;
    const item = target?.closest<HTMLElement>("[data-id]");
    if (item?.dataset.id) onSelect(item.dataset.id);
  };
}

export function createDelegatedListHandler(onSelect: (id: string) => void) {
  return (event: Event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;

    const item = target.closest<HTMLElement>("[data-id]");
    const id = item?.dataset.id?.trim();

    if (id) onSelect(id);
  };
}

export function createDelegatedListHandler(onSelect: (id: string) => void) {
  return (event: Event) => {
    const target = event.target as HTMLElement | null;
    const item = target?.closest<HTMLElement>("[data-id]");
    if (item?.dataset.id) onSelect(item.dataset.id);
  };
}

import { useState } from "react";

export type Row = { id: string; name: string; score: number };

export function DataTable({ rows }: { rows: Row[] }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState<"name" | "score">("name");
  const visible = rows
    .filter((row) => row.name.toLowerCase().includes(query.toLowerCase()))
    .sort((a, b) =>
      sort === "name" ? a.name.localeCompare(b.name) : b.score - a.score,
    );

  return (
    <div>
      <label>
        Filter
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
        />
      </label>
      <button onClick={() => setSort("score")}>Sort by score</button>
      <table>
        <tbody>
          {visible.map((row) => (
            <tr key={row.id}>
              <td>{row.name}</td>
              <td>{row.score}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

