import { useMemo, useState } from "react";

export type Row = { id: string; name: string; score: number };

type SortState = { key: "name" | "score"; direction: "asc" | "desc" };

export function DataTable({ rows }: { rows: Row[] }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState<SortState>({
    key: "name",
    direction: "asc",
  });

  const visible = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    const direction = sort.direction === "asc" ? 1 : -1;

    return [...rows]
      .filter((row) => row.name.toLowerCase().includes(normalizedQuery))
      .sort((a: Row, b: Row) => {
        const result =
          sort.key === "name"
            ? a.name.localeCompare(b.name)
            : a.score - b.score;

        return result * direction;
      });
  }, [rows, query, sort]);

  function getAriaSort(key: SortState["key"]) {
    if (sort.key !== key) return "none";
    return sort.direction === "asc" ? "ascending" : "descending";
  }

  function toggleSort(key: SortState["key"]) {
    setSort((current) =>
      current.key === key
        ? {
            key,
            direction: current.direction === "asc" ? "desc" : "asc",
          }
        : { key, direction: "asc" },
    );
  }

  return (
    <div>
      <label>
        Filter
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
        />
      </label>
      <table>
        <thead>
          <tr>
            <th aria-sort={getAriaSort("name")}>
              <button onClick={() => toggleSort("name")}>Name</button>
            </th>
            <th aria-sort={getAriaSort("score")}>
              <button onClick={() => toggleSort("score")}>Score</button>
            </th>
          </tr>
        </thead>
        <tbody>
          {visible.map((row) => (
            <tr key={row.id}>
              <td>{row.name}</td>
              <td>{row.score}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

