import { useMemo, useState } from "react";

type FormValue = { name: string; email: string };
type Step = 0 | 1;

function validateStep(step: Step, value: FormValue): string {
  if (step === 0 && !value.name.trim()) return "Enter your name";
  if (step === 1 && !value.email.trim()) return "Enter your email";
  if (step === 1 && !value.email.includes("@")) return "Enter a valid email";
  return "";
}

export function MultiStepForm({
  onSubmit,
}: {
  onSubmit: (value: FormValue) => void;
}) {
  const [step, setStep] = useState<Step>(0);
  const [value, setValue] = useState<FormValue>({ name: "", email: "" });
  const [submitted, setSubmitted] = useState(false);
  const error = useMemo(() => validateStep(step, value), [step, value]);

  function update(field: keyof FormValue, nextValue: string) {
    setValue((current) => ({ ...current, [field]: nextValue }));
  }

  return (
    <form
      noValidate
      onSubmit={(event) => {
        event.preventDefault();
        setSubmitted(true);

        if (error) return;

        if (step === 0) {
          setSubmitted(false);
          setStep(1);
          return;
        }

        onSubmit({
          name: value.name.trim(),
          email: value.email.trim(),
        });
      }}
    >
      {step === 0 ? (
        <label>
          Name
          <input
            aria-invalid={Boolean(submitted && error)}
            value={value.name}
            onChange={(event) => update("name", event.target.value)}
          />
        </label>
      ) : (
        <label>
          Email
          <input
            aria-invalid={Boolean(submitted && error)}
            inputMode="email"
            value={value.email}
            onChange={(event) => update("email", event.target.value)}
          />
        </label>
      )}
      {submitted && error ? <p>{error}</p> : null}
      {step === 1 ? (
        <button type="button" onClick={() => setStep(0)}>
          Back
        </button>
      ) : null}
      <button type="submit">{step === 0 ? "Next" : "Submit"}</button>
    </form>
  );
}

