export function createCancellableTask<T>(
  task: (signal: AbortSignal) => Promise<T>,
) {
  const controller = new AbortController();
  let cancelled = false;

  const promise = Promise.resolve().then(() => task(controller.signal));

  return {
    promise,
    cancel: () => {
