export class AsyncQueue {
  private tail: Promise<unknown> = Promise.resolve();
  private pending = 0;

  add<T>(job: () => Promise<T>): Promise<T> {
    this.pending += 1;

    const run = this.tail.then(job, job);
    this.tail = run
      .catch(() => undefined)
      .finally(() => {
        this.pending -= 1;
      });

    return run;
  }

  size(): number {
    return this.pending;
  }

  onIdle(): Promise<void> {
    return this.tail.then(() => undefined);
  }
}

