import { useState } from "react";

export function usePagination<T>(items: T[], pageSize: number) {
  const [page, setPage] = useState(1);
  const pageCount = Math.ceil(items.length / pageSize);
  const currentItems = items.slice((page - 1) * pageSize, page * pageSize);

  return { page, pageCount, currentItems, setPage };
}

import { useMemo, useState } from "react";
export function usePagination<T>(items: T[], pageSize: number) {
  const [page, setPage] = useState(1);
  const pageCount = Math.max(1, Math.ceil(items.length / pageSize));
  const currentItems = useMemo(
    () => items.slice((page - 1) * pageSize, page * pageSize),
    [items, page, pageSize],
  );
  return {
    page,
    pageCount,
    currentItems,
    setPage: (next: number) => setPage(Math.min(pageCount, Math.max(1, next))),
  };
}

import { useCallback, useEffect, useMemo, useState } from "react";

export function usePagination<T>(items: T[], pageSize: number) {
  const [page, setPageState] = useState(1);
  const safePageSize = Math.max(1, pageSize);
  const pageCount = Math.max(1, Math.ceil(items.length / safePageSize));
  const safePage = Math.min(page, pageCount);

  useEffect(() => {
    setPageState((current) => Math.min(current, pageCount));
  }, [pageCount]);

  const currentItems = useMemo(
    () => items.slice((safePage - 1) * safePageSize, safePage * safePageSize),
    [items, safePage, safePageSize],
  );

  const setPage = useCallback(
    (next: number) =>
      setPageState(Math.min(pageCount, Math.max(1, Math.trunc(next)))),
    [pageCount],
  );

  return {
    page: safePage,
    pageCount,
    currentItems,
    setPage,
  };
}

