}

export function createLazyLoader(load: (id: string) => void) {
  const loaded = new Set<string>();

  return (entries: Array<{ isIntersecting: boolean; target: Element }>) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;

      const id = (entry.target as HTMLElement).dataset.id?.trim();
      if (!id || loaded.has(id)) return;

      loaded.add(id);
      load(id);
    });
  };
}

