export type Row = { id: string; name: string; role: string };

export function applyRowEdit(
  rows: Row[],
  id: string,
  patch: Partial<Omit<Row, "id">>,
): Row[] {
  const entries = Object.entries(patch).filter(([, value]) => value !== undefined);
  if (entries.length === 0) return rows;

  let changed = false;
  const safePatch = Object.fromEntries(entries) as Partial<Omit<Row, "id">>;

  const nextRows = rows.map((row) => {
    if (row.id !== id) return row;
    changed = true;
    return { ...row, ...safePatch };
  });

  return changed ? nextRows : rows;
}

