export type TreeNode = { id: string; label?: string; children?: TreeNode[] };
export type FlatNode = Omit<TreeNode, "children"> & { depth: number };

export function flattenTree(nodes: TreeNode[]): FlatNode[] {
  const toFlatNode = (node: TreeNode, depth: number): FlatNode => ({
    id: node.id,
    ...(node.label === undefined ? {} : { label: node.label }),
    depth,
  });

  return nodes.flatMap((node) => [
    toFlatNode(node, 0),
    ...(node.children ?? []).map((child) => toFlatNode(child, 1)),
  ]);
}

export type TreeNode = { id: string; label?: string; children?: TreeNode[] };
export type FlatNode = Omit<TreeNode, "children"> & { depth: number };

export function flattenTree(nodes: TreeNode[]): FlatNode[] {
  const result: FlatNode[] = [];
  function visit(node: TreeNode, depth: number) {
    const { children: _children, ...rest } = node;
    result.push({ ...rest, depth });
    node.children?.forEach((child) => visit(child, depth + 1));
  }
  nodes.forEach((node) => visit(node, 0));
  return result;
}

export type TreeNode = { id: string; label?: string; children?: TreeNode[] };
export type FlatNode = Omit<TreeNode, "children"> & { depth: number };

export function flattenTree(nodes: TreeNode[]): FlatNode[] {
  const result: FlatNode[] = [];
  const stack = nodes
    .map((node) => ({ node, depth: 0 }))
    .reverse();

  while (stack.length) {
    const current = stack.pop();
    if (!current) continue;

    const { children: _children, ...rest } = current.node;
    result.push({ ...rest, depth: current.depth });

    [...(current.node.children ?? [])]
      .reverse()
      .forEach((child) => stack.push({ node: child, depth: current.depth + 1 }));
  }

  return result;
}

