export function getVariableVirtualWindow(
  heights: number[],
  scrollTop: number,
  containerHeight: number,
) {
  let offsetTop = 0;
  let startIndex = 0;

  while (
    startIndex < heights.length &&
    offsetTop + (heights[startIndex] ?? 0) <= scrollTop
  ) {
    offsetTop += heights[startIndex] ?? 0;
    startIndex += 1;
  }

  let endIndex = startIndex;
  let visibleHeight = 0;

  while (endIndex < heights.length && visibleHeight < containerHeight) {
    visibleHeight += heights[endIndex] ?? 0;
    endIndex += 1;
  }

  return { startIndex, endIndex, offsetTop };
}

export function getVariableVirtualWindow(
  heights: number[],
  scrollTop: number,
  containerHeight: number,
) {
  const offsets = heights.reduce<number[]>((acc, height) => {
    acc.push((acc.at(-1) ?? 0) + height);
    return acc;
  }, []);
  const foundStartIndex = offsets.findIndex((offset) => offset > scrollTop);
  const startIndex =
    foundStartIndex === -1 ? Math.max(0, heights.length - 1) : foundStartIndex;
  let endIndex = startIndex;
  while (
    endIndex < heights.length &&
    (offsets[endIndex] ?? Number.POSITIVE_INFINITY) <=
      scrollTop + containerHeight
  )
    endIndex += 1;
  return {
    startIndex,
    endIndex: Math.min(heights.length, endIndex + 1),
    offsetTop: startIndex === 0 ? 0 : (offsets[startIndex - 1] ?? 0),
  };
}

export function getVariableVirtualWindow(
  heights: number[],
  scrollTop: number,
  containerHeight: number,
) {
  const offsets = heights.reduce<number[]>((acc, height) => {
    acc.push((acc.at(-1) ?? 0) + Math.max(0, height));
    return acc;
  }, []);

  if (heights.length === 0) {
    return { startIndex: 0, endIndex: 0, offsetTop: 0 };
  }

  const safeScrollTop = Math.max(0, scrollTop);
  const safeContainerHeight = Math.max(0, containerHeight);
  const foundStartIndex = offsets.findIndex((offset) => offset > safeScrollTop);
  const startIndex =
    foundStartIndex === -1 ? Math.max(0, heights.length - 1) : foundStartIndex;

  let endIndex = startIndex;
  while (
    endIndex < heights.length &&
    (offsets[endIndex] ?? Number.POSITIVE_INFINITY) <=
      safeScrollTop + safeContainerHeight
  ) {
    endIndex += 1;
  }

  return {
    startIndex,
    endIndex: Math.min(heights.length, endIndex + 1),
    offsetTop: startIndex === 0 ? 0 : (offsets[startIndex - 1] ?? 0),
  };
}

