import { useState } from "react";

type Toast = {
  id: number;
  message: string;
};

export function ToastManager() {
  const [toasts, setToasts] = useState<Toast[]>([]);

  return (
    <div>
      <button
        onClick={() =>
          setToasts([...toasts, { id: Date.now(), message: "Saved" }])
        }
      >
        Show toast
      </button>
      <div>
        {toasts.map((toast) => (
          <p key={toast.id}>{toast.message}</p>
        ))}
      </div>
    </div>
  );
}

import { useState } from 'react';

type Toast = {
  id: number;
  message: string;
};

export function ToastManager() {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const showToast = () => {
    const id = Date.now();

    setToasts((items) => [
      ...items,

      {
        id,

        message: 'Saved',
      },
    ]);

    setTimeout(() => {
      toasts.filter((toast) => toast.id !== id);
    }, 3000);
  };
  return (
    <div>
      <button onClick={showToast}>Show toast</button>
      <div aria-live="polite">
        {toasts.map((toast) => (
          <p key={toast.id}>{toast.message}</p>
        ))}
      </div>
    </div>
  );
}

import { useCallback, useRef, useState } from "react";

type Toast = {
  id: number;
  message: string;
};

export function ToastManager() {
  const nextIdRef = useRef(0);
  const [toasts, setToasts] = useState<Toast[]>([]);

  const dismiss = useCallback((id: number) => {
    setToasts((items) => items.filter((toast) => toast.id !== id));
  }, []);

  const showToast = useCallback(() => {
    const id = nextIdRef.current;
    nextIdRef.current += 1;

    setToasts((items) => [...items, { id, message: "Saved" }]);

    window.setTimeout(() => {
      dismiss(id);
    }, 3000);
  }, [dismiss]);

  return (
    <div>
      <button onClick={showToast}>Show toast</button>
      <div aria-live="polite" aria-relevant="additions removals">
        {toasts.map((toast) => (
          <p key={toast.id}>
            {toast.message}
            <button type="button" onClick={() => dismiss(toast.id)}>
              Dismiss
            </button>
          </p>
        ))}
      </div>
    </div>
  );
}

